.content-box {
  width: calc(100% - 5px);
  height: 300px;
  margin: -20px 0px 20px 0px;
  padding-bottom: 22px;

  .d_cb_title {
    height: 40px;
  }

  .d_chart_parent {
    height: 260px;
    display: flex;
    justify-content: space-around;
  }

  .d_w33 {
    width: 33.33%;
    background-color: #fff;
  }

  .d_w100 {
    width: 100%;
    height: 100%;
  }

  .d_hcenter {
    display: flex;
    justify-content: center
  }

  .d_vhcenter {
    display: flex;
    align-items: center;
    justify-content: center
  }

  .d_start {
    display: flex;
    justify-content: flex-start;
  }

  .s_desc {
    font-size: 13px;
    margin-top: 12px
  }

  .i_img {
    width: 50px;
    height: 50px;
  }

  .d_l12 {
    margin-left: 12px;
  }

  .d_dev_info {
    margin-bottom: 12px;
  }
}

.el-col-6 {
  height: 30px !important;
}

.page_title_pie {
  font-size: 12px;
  color: #374c78;
  font-weight: 600;
  line-height: 30px;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  margin-bottom: 5px;
  margin-right: 5px;
  position: relative;
  border-bottom: 1px #e4e7ed solid;

  &::before {
    content: "";
    width: 4px;
    height: 15px;
    background: #3a86ff;
    border-radius: 6px;
    margin-right: 10px;
    display: inline-block;
  }
}

.query-btn {
  height: 24px !important;
  padding: 3px 5px !important;
  border: none !important;
  font-size: 10px !important;
  margin-bottom: 2px !important;
}

.query-btn:active, .is-active {
  background-color: #ecf5ff !important;
}
